<?php
namespace App\Filament\Resources;
use App\Filament\Resources\VoiceReportResource\Pages; use App\Filament\Resources\VoiceReportResource\RelationManagers; use App\Models\DiscordChannel; use App\Models\VoiceReport; use Filament\Forms; use Filament\Forms\Form; use Filament\Notifications\Notification; use Filament\Resources\Resource; use Filament\Tables; use Filament\Tables\Table;
class VoiceReportResource extends Resource { protected static ?string $model=VoiceReport::class; protected static ?string $modelLabel='signalement'; protected static ?string $pluralModelLabel='signalements'; protected static ?string $navigationIcon='heroicon-o-flag'; protected static ?string $navigationLabel='Signalements'; protected static ?string $navigationGroup='Modération';
 public static function canViewAny(): bool{return auth()->user()?->canManageReports() ?? false;}
 public static function canCreate(): bool{return auth()->user()?->canManageReports() ?? false;}
 public static function canEdit($record): bool{return auth()->user()?->canManageReports() ?? false;}
 public static function canDelete($record): bool{return auth()->user()?->isSuperAdmin() ?? false;}
 public static function form(Form $form): Form{return $form->schema([Forms\Components\Section::make('Signalement')->columns(2)->schema([Forms\Components\Select::make('discord_guild_id')->label('Serveur')->relationship('guild','name')->required()->searchable()->preload(),Forms\Components\Select::make('discord_channel_id')->label('Salon vocal')->relationship('channel','name',fn($query)=>$query->whereIn('type',DiscordChannel::VOICE_TYPES))->required()->searchable()->preload(),Forms\Components\TextInput::make('reported_user_discord_id')->label('Utilisateur signalé')->formatStateUsing(fn($state,$record)=>$record?->reportedUserName()??$state)->disabled(),Forms\Components\TextInput::make('reporter_user_discord_id')->label('Auteur')->formatStateUsing(fn($state,$record)=>$record?->reporterUserName()??$state)->disabled(),Forms\Components\TextInput::make('reason')->label('Motif')->required(),Forms\Components\Select::make('status')->label('Statut')->options(['pending'=>'En attente','under_review'=>'En revue','actioned'=>'Action effectuée','dismissed'=>'Classé sans suite','expired'=>'Expiré','deleted'=>'Supprimé'])->default('pending')->required(),Forms\Components\DateTimePicker::make('reported_at')->label('Signalé le')->required()->default(now()),Forms\Components\Textarea::make('comment')->label('Commentaire')->columnSpanFull()])]);}
 public static function table(Table $table): Table{return $table->poll('10s')->columns([Tables\Columns\TextColumn::make('reported_at')->label('Signalé le')->dateTime()->sortable(),Tables\Columns\TextColumn::make('guild.name')->label('Serveur')->searchable(),Tables\Columns\TextColumn::make('channel.name')->label('Salon')->searchable(),Tables\Columns\TextColumn::make('reported_user_discord_id')->label('Utilisateur')->formatStateUsing(fn($state,VoiceReport $record):string=>$record->reportedUserName())->description(fn(VoiceReport $record):string=>$record->reported_user_discord_id)->copyable()->searchable(),Tables\Columns\TextColumn::make('reason')->label('Motif')->searchable(),Tables\Columns\TextColumn::make('recording.track_count')->label('Pistes audio')->formatStateUsing(fn($state):string=>((int)$state)>0?$state.' piste(s)':'Aucun'),Tables\Columns\TextColumn::make('status')->label('Statut')->formatStateUsing(fn(string $state):string=>match($state){'pending'=>'En attente','under_review'=>'En revue','actioned'=>'Action effectuée','dismissed'=>'Classé sans suite','expired'=>'Expiré','deleted'=>'Supprimé',default=>$state})->badge()->color(fn(string $state):string=>match($state){'pending'=>'warning','under_review'=>'info','actioned'=>'success','dismissed','expired','deleted'=>'gray',default=>'gray'})])->filters([Tables\Filters\SelectFilter::make('status')->label('Statut')->options(['pending'=>'En attente','under_review'=>'En revue','actioned'=>'Action effectuée','dismissed'=>'Classé sans suite','expired'=>'Expiré','deleted'=>'Supprimé'])])->actions([Tables\Actions\EditAction::make()])->bulkActions([Tables\Actions\BulkActionGroup::make([Tables\Actions\BulkAction::make('markUnderReview')->label('Prendre en revue')->icon('heroicon-o-eye')->color('info')->action(function($records): void {$count=$records->count();$records->each->update(['status'=>'under_review']);Notification::make()->title($count.' signalement(s) pris en revue')->success()->send();}),Tables\Actions\BulkAction::make('markActioned')->label('Marquer comme traité')->icon('heroicon-o-check-circle')->color('success')->requiresConfirmation()->action(function($records): void {$count=$records->count();$records->each->update(['status'=>'actioned']);Notification::make()->title($count.' signalement(s) marqué(s) comme traité(s)')->success()->send();}),Tables\Actions\BulkAction::make('dismissSelected')->label('Classer sans suite')->icon('heroicon-o-archive-box')->color('gray')->requiresConfirmation()->modalHeading('Classer les signalements sélectionnés sans suite ?')->action(function($records): void {$count=$records->count();$records->each->update(['status'=>'dismissed']);Notification::make()->title($count.' signalement(s) classé(s) sans suite')->success()->send();}),Tables\Actions\BulkAction::make('deleteAudioSelected')->label('Supprimer les audios')->icon('heroicon-o-speaker-x-mark')->color('danger')->requiresConfirmation()->modalHeading('Supprimer les audios des signalements sélectionnés ?')->modalDescription('Les fichiers audio associés seront supprimés. Les signalements resteront visibles.')->action(function($records): void {$count=0;$records->each(function(VoiceReport $record) use (&$count): void {if($record->recording){$record->recording->delete();$count++;}});Notification::make()->title($count.' enregistrement(s) audio supprimé(s)')->success()->send();}),Tables\Actions\DeleteBulkAction::make()->label('Supprimer les signalements')])]);}
 public static function getRelations(): array{return [RelationManagers\ActionsRelationManager::class];}
 public static function getPages():array{return ['index'=>Pages\ListVoiceReports::route('/'),'create'=>Pages\CreateVoiceReport::route('/create'),'edit'=>Pages\EditVoiceReport::route('/{record}/edit')];}}
